import type { Plugin } from "vite";
import { defineConfig } from "vite";
import { tanstackStart } from "@tanstack/react-start/plugin/vite";
import viteReact from "@vitejs/plugin-react";
import tailwindcss from "@tailwindcss/vite";
import { nitro } from "nitro/vite";

/**
 * Finish PGLite bootstrap during dev-server setup (before traffic). Vite awaits
 * async `configureServer` hooks. Production: `src/lib/db` kicks `ensureDbReady`
 * on import.
 */
function pgliteBootstrapPlugin(): Plugin {
  return {
    name: "app-builder:pglite-bootstrap",
    apply: "serve",
    async configureServer(server) {
      try {
        const mod = (await server.ssrLoadModule("/src/lib/db.ts")) as {
          ensureDbReady?: () => Promise<void>;
        };
        if (typeof mod.ensureDbReady === "function") {
          await mod.ensureDbReady();
        }
      } catch (err) {
        console.error("[app-builder] DB bootstrap failed:", err);
        throw err;
      }
    },
  };
}

/**
 * Live-preview OAuth popup — handled HERE so the agent never has to create a
 * `/auth/popup` route (and cannot break it by scaffolding a React page that
 * paints the full app shell in the popup).
 *
 * `signIn` (client.ts) opens `/auth/popup?providerId=…` in a top-level window.
 * This middleware runs before TanStack Start, calls `handleAuthPopupRequest`,
 * and returns the 302 / completion HTML. Deployed apps do not use the popup
 * (full-page OAuth redirect), so `apply: "serve"` is enough.
 */
function authPopupPlugin(): Plugin {
  return {
    name: "app-builder:auth-popup",
    apply: "serve",
    configureServer(server) {
      // Register immediately (not in a returned post-hook) so we run BEFORE
      // TanStack Start / the SPA HTML fallback. A model-authored
      // `src/routes/auth/popup.tsx` React page must never win this path.
      server.middlewares.use(async (req, res, next) => {
        try {
          const rawUrl = req.url ?? "";
          const pathOnly = rawUrl.split("?", 1)[0] ?? "";
          if (pathOnly !== "/auth/popup") {
            next();
            return;
          }
          if ((req.method ?? "GET").toUpperCase() !== "GET") {
            res.statusCode = 405;
            res.setHeader("content-type", "text/plain; charset=utf-8");
            res.end("Method Not Allowed");
            return;
          }

          const host = String(req.headers["x-forwarded-host"] ?? req.headers.host ?? "localhost:8080");
          const proto = String(
            req.headers["x-forwarded-proto"] ??
              ((req.socket as { encrypted?: boolean } | undefined)?.encrypted ? "https" : "http"),
          );
          const requestHeaders = new Headers();
          for (const [key, value] of Object.entries(req.headers)) {
            if (value === undefined) continue;
            if (Array.isArray(value)) {
              for (const v of value) requestHeaders.append(key, v);
            } else {
              requestHeaders.set(key, value);
            }
          }
          // Ensure Host is the public preview host so Better Auth's dynamic
          // baseURL / redirect_uri match the popup origin.
          if (!requestHeaders.has("host")) requestHeaders.set("host", host);

          const request = new Request(`${proto}://${host}${rawUrl}`, {
            method: "GET",
            headers: requestHeaders,
          });

          const mod = (await server.ssrLoadModule("/src/lib/auth/popup.server.ts")) as {
            handleAuthPopupRequest: (req: Request) => Promise<Response>;
          };
          const response = await mod.handleAuthPopupRequest(request);

          res.statusCode = response.status;
          // Preserve multiple Set-Cookie headers (OAuth state + session).
          const setCookies =
            typeof response.headers.getSetCookie === "function"
              ? response.headers.getSetCookie()
              : [];
          response.headers.forEach((value, key) => {
            if (key.toLowerCase() === "set-cookie") return;
            res.setHeader(key, value);
          });
          for (const cookie of setCookies) {
            res.appendHeader("set-cookie", cookie);
          }
          const body = Buffer.from(await response.arrayBuffer());
          res.end(body);
        } catch (err) {
          console.error("[app-builder] /auth/popup handler failed:", err);
          if (!res.headersSent) {
            res.statusCode = 500;
            res.setHeader("content-type", "text/plain; charset=utf-8");
            res.end("auth popup failed");
          }
        }
      });
    },
  };
}

// `0.0.0.0:8080` is the live-preview contract — don't change host/port.
// Keep `nitro` gated to `build` (the Vercel deploy target): enabled in dev it
// opens a second dev-server port, which breaks the single-port preview.
// The dev server starts once `src/router.tsx` and `src/routes/` exist — see
// AGENTS.md § "First scaffold".
export default defineConfig(({ command }) => ({
  server: {
    host: "0.0.0.0",
    port: 8080,
    strictPort: true,
  },
  resolve: { tsconfigPaths: true },
  plugins: [
    pgliteBootstrapPlugin(),
    // Before tanstackStart so /auth/popup never falls through to the SPA.
    authPopupPlugin(),
    tailwindcss(),
    tanstackStart(),
    ...(command === "build" ? [nitro({ preset: "vercel" })] : []),
    viteReact(),
  ],
}));

import { Link } from "@tanstack/react-router";
import { AlertTriangle, ChevronRight } from "lucide-react";
import { DrawingStatusBadge } from "@/components/status-badges";
import {
  DRAWING_TYPE_LABELS,
  type Drawing,
  type Sequence,
} from "@/lib/types";
import { cn, formatDate, formatTons } from "@/lib/utils";

export function DrawingTable({
  drawings,
  sequences,
  compact,
}: {
  drawings: Drawing[];
  sequences: Sequence[];
  compact?: boolean;
}) {
  const seqMap = Object.fromEntries(sequences.map((s) => [s.id, s]));

  if (drawings.length === 0) {
    return (
      <div className="panel flex flex-col items-center justify-center px-6 py-16 text-center">
        <div className="text-sm font-medium text-[var(--color-fg)]">No drawings match</div>
        <p className="mt-1 max-w-sm text-sm text-[var(--color-muted)]">
          Adjust filters or clear the piece-mark search. Register is scoped to the active job.
        </p>
      </div>
    );
  }

  return (
    <div className="panel overflow-hidden">
      <div className="overflow-x-auto">
        <table className="w-full min-w-[720px] text-left text-sm">
          <thead>
            <tr className="border-b border-[var(--color-border)] bg-[var(--color-bg-elevated)] text-[11px] uppercase tracking-wider text-[var(--color-subtle)]">
              <th className="px-4 py-3 font-medium">Dwg #</th>
              <th className="px-4 py-3 font-medium">Title</th>
              {!compact && <th className="px-4 py-3 font-medium">Type</th>}
              <th className="px-4 py-3 font-medium">Rev</th>
              <th className="px-4 py-3 font-medium">Status</th>
              {!compact && <th className="px-4 py-3 font-medium">Sequence</th>}
              <th className="px-4 py-3 font-medium">Pieces</th>
              {!compact && <th className="px-4 py-3 font-medium">Issued</th>}
              <th className="px-2 py-3 font-medium" />
            </tr>
          </thead>
          <tbody>
            {drawings.map((d) => {
              const seq = d.sequenceId ? seqMap[d.sequenceId] : undefined;
              return (
                <tr
                  key={d.id}
                  className={cn(
                    "border-b border-[var(--color-border)]/70 transition-colors hover:bg-[var(--color-surface-2)]/60",
                    d.status === "on_hold" && "bg-[var(--color-warn-bg)]/40",
                  )}
                >
                  <td className="px-4 py-3">
                    <Link
                      to="/drawings/$drawingId"
                      params={{ drawingId: d.id }}
                      className="font-mono-num font-medium text-[var(--color-fg)] hover:underline"
                    >
                      {d.number}
                    </Link>
                    {d.status === "on_hold" && (
                      <AlertTriangle className="ml-1.5 inline size-3.5 text-[var(--color-warn)]" />
                    )}
                  </td>
                  <td className="max-w-[220px] px-4 py-3">
                    <div className="truncate font-medium">{d.title}</div>
                    {d.area && (
                      <div className="truncate text-xs text-[var(--color-muted)]">{d.area}</div>
                    )}
                  </td>
                  {!compact && (
                    <td className="px-4 py-3 text-[var(--color-muted)]">
                      {DRAWING_TYPE_LABELS[d.type]}
                    </td>
                  )}
                  <td className="px-4 py-3 font-mono-num">{d.currentRev}</td>
                  <td className="px-4 py-3">
                    <DrawingStatusBadge status={d.status} />
                  </td>
                  {!compact && (
                    <td className="px-4 py-3 text-xs text-[var(--color-muted)]">
                      {seq ? `Seq ${seq.number}` : "—"}
                    </td>
                  )}
                  <td className="px-4 py-3">
                    <div className="font-mono-num text-xs text-[var(--color-muted)]">
                      {d.pieceMarks.slice(0, 3).join(", ") || "—"}
                      {d.pieceMarks.length > 3 && ` +${d.pieceMarks.length - 3}`}
                    </div>
                    {d.tonnage != null && (
                      <div className="text-[11px] text-[var(--color-subtle)]">
                        {formatTons(d.tonnage)}
                      </div>
                    )}
                  </td>
                  {!compact && (
                    <td className="px-4 py-3 text-xs text-[var(--color-muted)]">
                      {formatDate(d.issuedDate)}
                    </td>
                  )}
                  <td className="px-2 py-3">
                    <Link
                      to="/drawings/$drawingId"
                      params={{ drawingId: d.id }}
                      className="inline-flex size-8 items-center justify-center rounded-[var(--radius-sm)] text-[var(--color-muted)] hover:bg-[var(--color-surface-2)] hover:text-[var(--color-fg)]"
                      aria-label={`Open ${d.number}`}
                    >
                      <ChevronRight className="size-4" />
                    </Link>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}

import { Link } from "@tanstack/react-router";
import {
  AlertTriangle,
  ChevronDown,
  ChevronRight,
  Layers,
} from "lucide-react";
import { useMemo, useState } from "react";
import { DrawingStatusBadge } from "@/components/status-badges";
import {
  DRAWING_TYPE_LABELS,
  type Drawing,
  type DrawingSet,
  type Sequence,
} from "@/lib/types";
import { rolledSetStatus, sheetsForSet } from "@/lib/store";
import { cn, formatDate, formatTons } from "@/lib/utils";

export function SetRegister({
  sets,
  drawings,
  sequences,
  defaultExpanded,
}: {
  sets: DrawingSet[];
  drawings: Drawing[];
  sequences: Sequence[];
  defaultExpanded?: boolean;
}) {
  const seqMap = useMemo(
    () => Object.fromEntries(sequences.map((s) => [s.id, s])),
    [sequences],
  );
  const [open, setOpen] = useState<Record<string, boolean>>(() => {
    if (!defaultExpanded) return {};
    return Object.fromEntries(sets.map((s) => [s.id, true]));
  });

  if (sets.length === 0) {
    return (
      <div className="panel flex flex-col items-center justify-center px-6 py-16 text-center">
        <div className="text-sm font-medium text-[var(--color-fg)]">
          No drawing sets match
        </div>
        <p className="mt-1 max-w-sm text-sm text-[var(--color-muted)]">
          Adjust filters or clear search. Sets are the parent packages; sheets live
          underneath each set.
        </p>
      </div>
    );
  }

  return (
    <div className="space-y-3">
      {sets.map((set) => {
        const sheets = sheetsForSet(drawings, set.id);
        const effective = rolledSetStatus(sheets, set.status);
        const holds = sheets.filter((d) => d.status === "on_hold").length;
        const tons = sheets.reduce((sum, d) => sum + (d.tonnage ?? 0), 0);
        const seq = set.sequenceId ? seqMap[set.sequenceId] : undefined;
        const isOpen = open[set.id] ?? false;

        return (
          <article key={set.id} className="panel overflow-hidden">
            <div
              className={cn(
                "flex flex-col gap-3 border-b border-[var(--color-border)] bg-[var(--color-bg-elevated)] px-4 py-3.5 sm:flex-row sm:items-center sm:justify-between sm:px-5",
                (effective === "on_hold" || holds > 0) && "bg-[var(--color-warn-bg)]/50",
              )}
            >
              <div className="flex min-w-0 items-start gap-2 sm:items-center">
                <button
                  type="button"
                  className="mt-0.5 inline-flex size-8 shrink-0 items-center justify-center rounded-[var(--radius-sm)] text-[var(--color-muted)] hover:bg-[var(--color-surface)] hover:text-[var(--color-fg)] sm:mt-0"
                  aria-expanded={isOpen}
                  aria-label={isOpen ? "Collapse sheets" : "Expand sheets"}
                  onClick={() =>
                    setOpen((prev) => ({ ...prev, [set.id]: !isOpen }))
                  }
                >
                  {isOpen ? (
                    <ChevronDown className="size-4" />
                  ) : (
                    <ChevronRight className="size-4" />
                  )}
                </button>
                <div className="min-w-0">
                  <div className="flex flex-wrap items-center gap-2">
                    <Link
                      to="/drawings/sets/$setId"
                      params={{ setId: set.id }}
                      className="font-mono-num text-sm font-semibold hover:underline"
                    >
                      {set.code}
                    </Link>
                    <DrawingStatusBadge status={effective} />
                    {(holds > 0 || effective === "on_hold") && (
                      <span className="inline-flex items-center gap-1 text-[11px] text-[var(--color-warn)]">
                        <AlertTriangle className="size-3" />
                        {holds || 1} hold{(holds || 1) === 1 ? "" : "s"}
                      </span>
                    )}
                  </div>
                  <Link
                    to="/drawings/sets/$setId"
                    params={{ setId: set.id }}
                    className="mt-0.5 block truncate font-medium hover:underline"
                  >
                    {set.name}
                  </Link>
                  <div className="mt-1 flex flex-wrap gap-x-3 gap-y-0.5 text-xs text-[var(--color-muted)]">
                    <span>{DRAWING_TYPE_LABELS[set.type]}</span>
                    <span className="font-mono-num">Set rev {set.currentRev}</span>
                    {seq && <span>Seq {seq.number}</span>}
                    <span>
                      {sheets.length} sheet{sheets.length === 1 ? "" : "s"}
                    </span>
                    {tons > 0 && (
                      <span className="font-mono-num">{formatTons(tons)}</span>
                    )}
                  </div>
                </div>
              </div>

              <div className="flex shrink-0 items-center gap-2 pl-10 sm:pl-0">
                <Link
                  to="/drawings/sets/$setId"
                  params={{ setId: set.id }}
                  className="inline-flex h-9 items-center gap-1.5 rounded-[var(--radius-md)] border border-[var(--color-border)] bg-[var(--color-surface)] px-3 text-xs font-medium text-[var(--color-muted)] hover:border-[var(--color-border-strong)] hover:text-[var(--color-fg)]"
                >
                  <Layers className="size-3.5" />
                  Open set
                </Link>
              </div>
            </div>

            {isOpen && (
              <div className="overflow-x-auto">
                <table className="w-full min-w-[640px] text-left text-sm">
                  <thead>
                    <tr className="border-b border-[var(--color-border)] text-[11px] uppercase tracking-wider text-[var(--color-subtle)]">
                      <th className="w-10 px-4 py-2 font-medium">#</th>
                      <th className="px-3 py-2 font-medium">Sheet</th>
                      <th className="px-3 py-2 font-medium">Title</th>
                      <th className="px-3 py-2 font-medium">Type</th>
                      <th className="px-3 py-2 font-medium">Rev</th>
                      <th className="px-3 py-2 font-medium">Status</th>
                      <th className="px-3 py-2 font-medium">Pieces</th>
                      <th className="px-3 py-2 font-medium">Issued</th>
                      <th className="px-2 py-2" />
                    </tr>
                  </thead>
                  <tbody>
                    {sheets.length === 0 && (
                      <tr>
                        <td
                          colSpan={9}
                          className="px-5 py-6 text-[var(--color-muted)]"
                        >
                          No sheets in this set yet.
                        </td>
                      </tr>
                    )}
                    {sheets.map((d) => (
                      <tr
                        key={d.id}
                        className={cn(
                          "border-b border-[var(--color-border)]/60 transition-colors hover:bg-[var(--color-surface-2)]/50",
                          d.status === "on_hold" && "bg-[var(--color-warn-bg)]/30",
                        )}
                      >
                        <td className="px-4 py-2.5 font-mono-num text-xs text-[var(--color-subtle)]">
                          {d.sheetIndex}
                        </td>
                        <td className="px-3 py-2.5">
                          <Link
                            to="/drawings/$drawingId"
                            params={{ drawingId: d.id }}
                            className="font-mono-num font-medium hover:underline"
                          >
                            {d.number}
                          </Link>
                          {d.status === "on_hold" && (
                            <AlertTriangle className="ml-1.5 inline size-3.5 text-[var(--color-warn)]" />
                          )}
                        </td>
                        <td className="max-w-[200px] truncate px-3 py-2.5 text-[var(--color-muted)]">
                          {d.title}
                        </td>
                        <td className="px-3 py-2.5 text-xs text-[var(--color-muted)]">
                          {DRAWING_TYPE_LABELS[d.type]}
                        </td>
                        <td className="px-3 py-2.5 font-mono-num">{d.currentRev}</td>
                        <td className="px-3 py-2.5">
                          <DrawingStatusBadge status={d.status} />
                        </td>
                        <td className="px-3 py-2.5 font-mono-num text-xs text-[var(--color-muted)]">
                          {d.pieceMarks.slice(0, 3).join(", ") || "—"}
                          {d.pieceMarks.length > 3 && ` +${d.pieceMarks.length - 3}`}
                        </td>
                        <td className="px-3 py-2.5 text-xs text-[var(--color-muted)]">
                          {formatDate(d.issuedDate)}
                        </td>
                        <td className="px-2 py-2.5">
                          <Link
                            to="/drawings/$drawingId"
                            params={{ drawingId: d.id }}
                            className="inline-flex size-8 items-center justify-center rounded-[var(--radius-sm)] text-[var(--color-muted)] hover:bg-[var(--color-surface-2)] hover:text-[var(--color-fg)]"
                            aria-label={`Open sheet ${d.number}`}
                          >
                            <ChevronRight className="size-4" />
                          </Link>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </article>
        );
      })}
    </div>
  );
}

import { Link, useRouterState } from "@tanstack/react-router";
import {
  Building2,
  ClipboardList,
  FileStack,
  LayoutDashboard,
  Menu,
  MessageSquareWarning,
  Route as RouteIcon,
  Search,
  X,
} from "lucide-react";
import { useMemo, useState } from "react";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Select } from "@/components/ui/select";
import { useAppStore } from "@/lib/store";
import { cn } from "@/lib/utils";

const nav: {
  to: string;
  label: string;
  icon: typeof LayoutDashboard;
  exact?: boolean;
}[] = [
  { to: "/", label: "Command Center", icon: LayoutDashboard, exact: true },
  { to: "/drawings", label: "Drawing Sets", icon: FileStack },
  { to: "/sequences", label: "Erection Sequences", icon: RouteIcon },
  { to: "/submittals", label: "Submittals", icon: ClipboardList },
  { to: "/rfis", label: "RFI Log", icon: MessageSquareWarning },
  { to: "/projects", label: "Jobs", icon: Building2 },
];

export function AppShell({
  children,
  title,
  subtitle,
  actions,
}: {
  children: React.ReactNode;
  title: string;
  subtitle?: string;
  actions?: React.ReactNode;
}) {
  const [open, setOpen] = useState(false);
  const pathname = useRouterState({ select: (s) => s.location.pathname });
  const projects = useAppStore((s) => s.projects);
  const selectedProjectId = useAppStore((s) => s.selectedProjectId);
  const setSelectedProjectId = useAppStore((s) => s.setSelectedProjectId);
  const setFilters = useAppStore((s) => s.setFilters);
  const filters = useAppStore((s) => s.filters);
  const drawings = useAppStore((s) => s.drawings);
  const rfis = useAppStore((s) => s.rfis);

  const project = projects.find((p) => p.id === selectedProjectId) ?? projects[0];
  const openHolds = useMemo(
    () =>
      drawings.filter(
        (d) => d.projectId === project?.id && d.status === "on_hold",
      ).length,
    [drawings, project?.id],
  );
  const openRfis = useMemo(
    () =>
      rfis.filter((r) => r.projectId === project?.id && r.status === "open")
        .length,
    [rfis, project?.id],
  );

  return (
    <div className="min-h-dvh bg-[var(--color-bg)] text-[var(--color-fg)]">
      <div className="flex min-h-dvh">
        <aside className="hidden w-64 shrink-0 flex-col border-r border-[var(--color-border)] bg-[var(--color-bg-elevated)] lg:flex">
          <div className="border-b border-[var(--color-border)] px-5 py-5">
            <Link to="/" className="block">
              <div className="text-[11px] font-medium uppercase tracking-[0.18em] text-[var(--color-subtle)]">
                Steel fab & erection
              </div>
              <div className="mt-1 font-semibold tracking-tight text-[var(--color-fg)]">
                PieceMark
              </div>
              <div className="mt-0.5 text-xs text-[var(--color-muted)]">
                Drawings control
              </div>
            </Link>
          </div>

          <div className="space-y-2 border-b border-[var(--color-border)] px-4 py-4">
            <label className="text-[11px] font-medium uppercase tracking-wider text-[var(--color-subtle)]">
              Active job
            </label>
            <Select
              value={project?.id ?? ""}
              onChange={(e) => setSelectedProjectId(e.target.value)}
              aria-label="Select job"
            >
              {projects.map((p) => (
                <option key={p.id} value={p.id}>
                  {p.jobNumber} — {p.name.split("—")[0].trim()}
                </option>
              ))}
            </Select>
            {project && (
              <div className="rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] p-3 text-xs text-[var(--color-muted)]">
                <div className="font-mono-num text-[var(--color-fg)]">
                  {project.jobNumber}
                </div>
                <div className="mt-1 line-clamp-2">{project.client}</div>
                <div className="mt-2 flex gap-3 text-[11px]">
                  <span className="text-[var(--color-warn)]">
                    {openHolds} holds
                  </span>
                  <span className="text-[var(--color-info)]">
                    {openRfis} open RFIs
                  </span>
                </div>
              </div>
            )}
          </div>

          <nav className="flex-1 space-y-0.5 p-3">
            {nav.map((item) => {
              const active = item.exact
                ? pathname === item.to
                : pathname === item.to || pathname.startsWith(item.to + "/");
              const Icon = item.icon;
              return (
                <Link
                  key={item.to}
                  to={item.to}
                  className={cn(
                    "flex items-center gap-3 rounded-[var(--radius-md)] px-3 py-2.5 text-sm transition-colors",
                    active
                      ? "bg-[var(--color-surface-2)] text-[var(--color-fg)]"
                      : "text-[var(--color-muted)] hover:bg-[var(--color-surface)] hover:text-[var(--color-fg)]",
                  )}
                >
                  <Icon className="size-4 shrink-0 opacity-80" />
                  {item.label}
                </Link>
              );
            })}
          </nav>

          <div className="border-t border-[var(--color-border)] p-4 text-[11px] leading-relaxed text-[var(--color-subtle)]">
            Built for detailers, fab shops, and ironworkers — not generic PM.
          </div>
        </aside>

        <div className="flex min-w-0 flex-1 flex-col">
          <header className="sticky top-0 z-30 border-b border-[var(--color-border)] bg-[var(--color-bg)]/90 backdrop-blur-md">
