import { createFileRoute, Link } from "@tanstack/react-router";
import {
  AlertTriangle,
  ArrowRight,
  FileWarning,
  Layers3,
  MessageSquareWarning,
} from "lucide-react";
import { useMemo } from "react";
import {
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from "recharts";
import { SetRegister } from "@/components/drawings/set-register";
import { DrawingTable } from "@/components/drawings/drawing-table";
import { AppShell } from "@/components/layout/app-shell";
import { StatCard } from "@/components/stat-card";
import {
  DrawingStatusBadge,
  RfiPriorityBadge,
  RfiStatusBadge,
  SequenceStatusBadge,
} from "@/components/status-badges";
import { Button } from "@/components/ui/button";
import {
  DRAWING_STATUS_LABELS,
  DRAWING_TYPE_LABELS,
  type DrawingStatus,
} from "@/lib/types";
import {
  filterDrawingSets,
  filterDrawings,
  projectMetrics,
  useAppStore,
  useSelectedProject,
} from "@/lib/store";
import { formatDate, formatTons } from "@/lib/utils";

export const Route = createFileRoute("/")({
  component: CommandCenter,
});

function CommandCenter() {
  const project = useSelectedProject();
  const drawings = useAppStore((s) => s.drawings);
  const drawingSets = useAppStore((s) => s.drawingSets);
  const sequences = useAppStore((s) => s.sequences);
  const rfis = useAppStore((s) => s.rfis);
  const filters = useAppStore((s) => s.filters);

  const metrics = useMemo(
    () => (project ? projectMetrics(project.id) : null),
    [project, drawings, rfis],
  );

  const projectSeqs = useMemo(
    () => sequences.filter((s) => s.projectId === project?.id),
    [sequences, project?.id],
  );

  const attentionDrawings = useMemo(() => {
    if (!project) return [];
    return drawings
      .filter(
        (d) =>
          d.projectId === project.id &&
          (d.status === "on_hold" ||
            d.status === "revise_resubmit" ||
            d.status === "submitted"),
      )
      .slice(0, 6);
  }, [drawings, project?.id]);

  const openRfis = useMemo(
    () =>
      rfis
        .filter((r) => r.projectId === project?.id && r.status === "open")
        .sort((a, b) => {
          const order = { critical: 0, high: 1, normal: 2, low: 3 };
          return order[a.priority] - order[b.priority];
        }),
    [rfis, project?.id],
  );

  const statusChart = useMemo(() => {
    if (!project) return [];
    const counts: Partial<Record<DrawingStatus, number>> = {};
    for (const d of drawings.filter((x) => x.projectId === project.id)) {
      counts[d.status] = (counts[d.status] ?? 0) + 1;
    }
    return (Object.keys(counts) as DrawingStatus[]).map((status) => ({
      status: DRAWING_STATUS_LABELS[status],
      count: counts[status] ?? 0,
      key: status,
    }));
  }, [drawings, project?.id]);

  const typeBreakdown = useMemo(() => {
    if (!project) return [];
    const map = new Map<string, number>();
    for (const d of drawings.filter((x) => x.projectId === project.id)) {
      const label = DRAWING_TYPE_LABELS[d.type];
      map.set(label, (map.get(label) ?? 0) + 1);
    }
    return [...map.entries()]
      .map(([name, count]) => ({ name, count }))
      .sort((a, b) => b.count - a.count);
  }, [drawings, project?.id]);

  const searchSets = useMemo(() => {
    if (!filters.query.trim() || !project) return [];
    return filterDrawingSets(drawingSets, drawings, filters, project.id);
  }, [drawingSets, drawings, filters, project?.id]);

  if (!project || !metrics) {
    return (
      <AppShell title="Command Center">
        <p className="text-[var(--color-muted)]">No projects loaded.</p>
      </AppShell>
    );
  }

  return (
    <AppShell
      title="Command Center"
      subtitle={`${project.jobNumber} · ${project.name}`}
      actions={
        <Button asChild size="sm" variant="secondary" className="hidden sm:inline-flex">
          <Link to="/drawings">
            Open register
            <ArrowRight className="size-3.5" />
          </Link>
        </Button>
      }
    >
      <div className="space-y-6">
        {/* Job banner */}
        <section className="panel relative overflow-hidden p-5 sm:p-6">
          <div className="pointer-events-none absolute inset-0 steel-grid opacity-30" />
          <div className="relative grid gap-4 lg:grid-cols-[1fr_auto] lg:items-end">
            <div>
              <div className="text-[11px] font-medium uppercase tracking-[0.16em] text-[var(--color-subtle)]">
                Active job
              </div>
              <h2 className="mt-1 text-xl font-semibold tracking-tight sm:text-2xl">
                {project.name}
              </h2>
              <p className="mt-2 max-w-2xl text-sm text-[var(--color-muted)]">
                {project.description}
              </p>
              <div className="mt-4 flex flex-wrap gap-x-5 gap-y-2 text-xs text-[var(--color-muted)]">
                <span>
                  GC: <span className="text-[var(--color-fg)]">{project.client}</span>
                </span>
                <span>
                  EOR:{" "}
                  <span className="text-[var(--color-fg)]">{project.engineer}</span>
                </span>
                <span>
                  Shop:{" "}
                  <span className="text-[var(--color-fg)]">{project.fabShop}</span>
                </span>
                <span>
                  Contract:{" "}
                  <span className="font-mono-num text-[var(--color-fg)]">
                    {formatTons(project.tonnage)}
                  </span>
                </span>
              </div>
            </div>
            <div className="flex flex-wrap gap-2 lg:flex-col lg:items-end">
              <div className="rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-bg-elevated)] px-4 py-3 text-right">
                <div className="text-[11px] uppercase tracking-wider text-[var(--color-subtle)]">
                  Target complete
                </div>
                <div className="font-mono-num text-lg font-medium">
                  {formatDate(project.targetComplete)}
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* KPI row */}
        <section className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4">
          <StatCard
            label="Drawing sets / sheets"
            value={`${metrics.setCount} / ${metrics.total}`}
            hint={`${metrics.fabReady} sheets ready for fab/field`}
          />
          <StatCard
            label="Released for fab / field"
            value={`${metrics.fabReadyPct}%`}
            hint={`${metrics.fabReady} of ${metrics.total} sheets`}
            tone="success"
          />
          <StatCard
            label="On hold / R&R"
            value={metrics.onHold + metrics.revise}
            hint={`${metrics.onHold} holds · ${metrics.revise} revise & resubmit`}
            tone={metrics.onHold + metrics.revise > 0 ? "warn" : "default"}
          />
          <StatCard
            label="Open RFIs"
            value={metrics.openRfis}
            hint={`${metrics.openSubs} packages in review`}
            tone={metrics.openRfis > 0 ? "danger" : "success"}
          />
        </section>

        {filters.query.trim() && (
          <section className="space-y-3">
            <h3 className="text-sm font-medium text-[var(--color-muted)]">
              Matching sets for “{filters.query}”
            </h3>
            <SetRegister
              sets={searchSets}
              drawings={drawings}
              sequences={projectSeqs}
              defaultExpanded
            />
          </section>
        )}

        <section className="grid gap-4 xl:grid-cols-5">
          {/* Status chart */}
          <div className="panel p-4 sm:p-5 xl:col-span-3">
            <div className="mb-4 flex items-center justify-between gap-3">
              <div>
                <h3 className="font-medium">Drawing status pipeline</h3>
                <p className="text-xs text-[var(--color-muted)]">
                  Where sheets sit in the shop / field release chain
                </p>
              </div>
              <Layers3 className="size-4 text-[var(--color-subtle)]" />
            </div>
            <div className="h-56 sm:h-64">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={statusChart} margin={{ top: 4, right: 8, left: -12, bottom: 40 }}>
                  <CartesianGrid stroke="var(--color-border)" strokeDasharray="3 3" vertical={false} />
                  <XAxis
                    dataKey="status"
                    tick={{ fill: "var(--color-subtle)", fontSize: 10 }}
                    interval={0}
                    angle={-28}
                    textAnchor="end"
                    height={60}
                  />
                  <YAxis
                    allowDecimals={false}
                    tick={{ fill: "var(--color-subtle)", fontSize: 11 }}
                  />
                  <Tooltip
                    contentStyle={{
                      background: "var(--color-surface)",
                      border: "1px solid var(--color-border)",
                      borderRadius: 8,
                      fontSize: 12,
                    }}
                  />
                  <Bar dataKey="count" radius={[4, 4, 0, 0]}>
                    {statusChart.map((entry) => (
                      <Cell
                        key={entry.key}
                        fill={
                          entry.key === "on_hold" || entry.key === "revise_resubmit"
                            ? "var(--color-warn)"
                            : entry.key === "issued_for_erection" ||
                                entry.key === "issued_for_fab"
                              ? "var(--color-success)"
                              : "var(--color-accent)"
                        }
                      />
                    ))}
                  </Bar>
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>

          {/* Type breakdown */}
          <div className="panel p-4 sm:p-5 xl:col-span-2">
            <h3 className="font-medium">By drawing type</h3>
            <p className="mb-4 text-xs text-[var(--color-muted)]">
              Shop, erection, AB, connections…
            </p>
            <ul className="space-y-2.5">
              {typeBreakdown.map((row) => {
                const max = typeBreakdown[0]?.count || 1;
                return (
                  <li key={row.name}>
                    <div className="mb-1 flex justify-between text-xs">
                      <span className="text-[var(--color-muted)]">{row.name}</span>
                      <span className="font-mono-num text-[var(--color-fg)]">
                        {row.count}
                      </span>
                    </div>
                    <div className="h-1.5 overflow-hidden rounded-full bg-[var(--color-bg-elevated)]">
                      <div
                        className="h-full rounded-full bg-[var(--color-accent)]/70"
                        style={{ width: `${(row.count / max) * 100}%` }}
                      />
                    </div>
                  </li>
                );
              })}
            </ul>
          </div>
        </section>

        <section className="grid gap-4 lg:grid-cols-2">
          {/* Needs attention */}
          <div className="panel overflow-hidden">
            <div className="flex items-center justify-between border-b border-[var(--color-border)] px-4 py-3 sm:px-5">
              <div className="flex items-center gap-2">
                <FileWarning className="size-4 text-[var(--color-warn)]" />
                <h3 className="font-medium">Needs attention</h3>
              </div>
              <Link
                to="/drawings"
                className="text-xs text-[var(--color-accent)] hover:underline"
              >
                Full register
              </Link>
            </div>
            <ul className="divide-y divide-[var(--color-border)]/70">
              {attentionDrawings.length === 0 && (
                <li className="px-5 py-8 text-center text-sm text-[var(--color-muted)]">
                  No holds, R&Rs, or pending reviews on this job.
                </li>
              )}
              {attentionDrawings.map((d) => (
                <li key={d.id}>
                  <Link
                    to="/drawings/$drawingId"
                    params={{ drawingId: d.id }}
                    className="flex items-start gap-3 px-4 py-3 transition-colors hover:bg-[var(--color-surface-2)]/50 sm:px-5"
                  >
                    <div className="min-w-0 flex-1">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="font-mono-num font-medium">{d.number}</span>
                        <DrawingStatusBadge status={d.status} />
                      </div>
                      <div className="mt-0.5 truncate text-sm text-[var(--color-muted)]">
                        {d.title}
                      </div>
                      {d.holdReason && (
                        <div className="mt-1 flex items-start gap-1.5 text-xs text-[var(--color-warn)]">
                          <AlertTriangle className="mt-0.5 size-3 shrink-0" />
                          <span className="line-clamp-2">{d.holdReason}</span>
                        </div>
                      )}
                    </div>
                    <span className="font-mono-num text-xs text-[var(--color-subtle)]">
                      Rev {d.currentRev}
                    </span>
                  </Link>
                </li>
              ))}
            </ul>
          </div>

          {/* Open RFIs */}
          <div className="panel overflow-hidden">
            <div className="flex items-center justify-between border-b border-[var(--color-border)] px-4 py-3 sm:px-5">
              <div className="flex items-center gap-2">
                <MessageSquareWarning className="size-4 text-[var(--color-danger)]" />
                <h3 className="font-medium">Open RFIs</h3>
              </div>
              <Link to="/rfis" className="text-xs text-[var(--color-accent)] hover:underline">
                RFI log
              </Link>
            </div>
            <ul className="divide-y divide-[var(--color-border)]/70">
              {openRfis.length === 0 && (
                <li className="px-5 py-8 text-center text-sm text-[var(--color-muted)]">
                  No open RFIs. Detailing can proceed without hold points.
                </li>
              )}
              {openRfis.map((r) => (
                <li key={r.id} className="px-4 py-3 sm:px-5">
                  <div className="flex flex-wrap items-center gap-2">
                    <span className="font-mono-num font-medium">{r.number}</span>
                    <RfiPriorityBadge priority={r.priority} />
                    <RfiStatusBadge status={r.status} />
                  </div>
                  <div className="mt-1 text-sm">{r.subject}</div>
                  <div className="mt-1 text-xs text-[var(--color-muted)]">
                    Due {formatDate(r.dueDate)} · {r.raisedBy}
                  </div>
                </li>
              ))}
            </ul>
          </div>
        </section>

        {/* Sequences strip */}
        <section className="panel p-4 sm:p-5">
          <div className="mb-4 flex items-center justify-between">
            <div>
              <h3 className="font-medium">Erection sequences</h3>
              <p className="text-xs text-[var(--color-muted)]">
                Release order for field — shop status rolls up by sequence
              </p>
            </div>
            <Link to="/sequences" className="text-xs text-[var(--color-accent)] hover:underline">
              Manage sequences
            </Link>
          </div>
          <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">
            {projectSeqs.map((seq) => {
              const seqDwgs = drawings.filter((d) => d.sequenceId === seq.id);
              const ready = seqDwgs.filter((d) =>
                ["issued_for_fab", "issued_for_erection", "approved", "aan"].includes(
                  d.status,
                ),
              ).length;
              return (
                <div
                  key={seq.id}
                  className="rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-bg-elevated)] p-4"
                >
                  <div className="flex items-start justify-between gap-2">
                    <div className="font-medium">{seq.name}</div>
                    <SequenceStatusBadge status={seq.status} />
                  </div>
                  <div className="mt-2 text-xs text-[var(--color-muted)]">
                    Grids {seq.grids} · {formatTons(seq.tonnage)}
                  </div>
                  <div className="mt-3 flex items-center justify-between text-xs">
                    <span className="text-[var(--color-subtle)]">
                      Sheets released
                    </span>
                    <span className="font-mono-num">
                      {ready}/{seqDwgs.length || "—"}
                    </span>
                  </div>
                  <div className="mt-1.5 h-1.5 overflow-hidden rounded-full bg-[var(--color-surface)]">
                    <div
                      className="h-full rounded-full bg-[var(--color-success)]/80"
                      style={{
                        width: `${seqDwgs.length ? (ready / seqDwgs.length) * 100 : 0}%`,
                      }}
                    />
                  </div>
                </div>
              );
            })}
          </div>
        </section>
      </div>
    </AppShell>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { useMemo } from "react";
import { AppShell } from "@/components/layout/app-shell";
import { ProjectStatusBadge } from "@/components/status-badges";
import { Button } from "@/components/ui/button";
import { projectMetrics, useAppStore } from "@/lib/store";
import { formatDate, formatTons } from "@/lib/utils";

export const Route = createFileRoute("/projects")({
  component: ProjectsPage,
});

function ProjectsPage() {
  const projects = useAppStore((s) => s.projects);
  const selectedProjectId = useAppStore((s) => s.selectedProjectId);
  const setSelectedProjectId = useAppStore((s) => s.setSelectedProjectId);
  const drawings = useAppStore((s) => s.drawings);
  const rfis = useAppStore((s) => s.rfis);
  const resetDemoData = useAppStore((s) => s.resetDemoData);

  const cards = useMemo(
    () =>
      projects.map((p) => ({
        project: p,
        metrics: projectMetrics(p.id),
      })),
    [projects, drawings, rfis],
  );

  return (
    <AppShell
      title="Jobs"
      subtitle="Steel fab & erection portfolio"
      actions={
        <Button
          variant="ghost"
          size="sm"
          onClick={() => {
            resetDemoData();
          }}
        >
          Reset demo
        </Button>
      }
    >
      <div className="space-y-4">
        <p className="max-w-2xl text-sm text-[var(--color-muted)]">
          Each job carries its own drawing register, erection sequences, submittal
          packages, and RFI log. Switch the active job from the sidebar to drive
          every other view.
        </p>

        <div className="grid gap-4 lg:grid-cols-1 xl:grid-cols-1">
          {cards.map(({ project, metrics }) => {
            const active = project.id === selectedProjectId;
            return (
              <article
                key={project.id}
                className={
                  active
                    ? "panel border-[var(--color-border-strong)] p-5 sm:p-6"
                    : "panel p-5 sm:p-6"
                }
              >
                <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-mono-num text-sm font-medium text-[var(--color-accent)]">
                        {project.jobNumber}
                      </span>
                      <ProjectStatusBadge status={project.status} />
                      {active && (
                        <span className="rounded-full bg-[var(--color-primary)]/15 px-2 py-0.5 text-[11px] font-medium uppercase tracking-wide text-[var(--color-primary)]">
                          Active
                        </span>
                      )}
                    </div>
                    <h2 className="mt-1 text-xl font-semibold tracking-tight">
                      {project.name}
                    </h2>
                    <p className="mt-2 max-w-2xl text-sm text-[var(--color-muted)]">
                      {project.description}
                    </p>
                    <dl className="mt-4 grid gap-2 text-sm sm:grid-cols-2">
                      <Item label="GC / Client" value={project.client} />
                      <Item label="Engineer of record" value={project.engineer} />
                      <Item label="Location" value={project.location} />
                      <Item label="Contract tonnage" value={formatTons(project.tonnage)} />
                      <Item label="Detailer" value={project.detailerFirm} />
                      <Item label="Fab shop" value={project.fabShop} />
                      <Item label="Start" value={formatDate(project.startDate)} />
                      <Item
                        label="Target complete"
                        value={formatDate(project.targetComplete)}
                      />
                    </dl>
                  </div>

                  <div className="grid w-full grid-cols-2 gap-2 sm:w-auto sm:min-w-[220px]">
                    <Metric label="Sheets" value={metrics.total} />
                    <Metric
                      label="Released"
                      value={`${metrics.fabReadyPct}%`}
                      tone="success"
                    />
                    <Metric
                      label="Holds"
                      value={metrics.onHold}
                      tone={metrics.onHold ? "warn" : "default"}
                    />
                    <Metric
                      label="Open RFIs"
                      value={metrics.openRfis}
                      tone={metrics.openRfis ? "danger" : "default"}
                    />
                  </div>
                </div>

                <div className="mt-5 flex flex-wrap gap-2 border-t border-[var(--color-border)] pt-4">
                  <Button
                    size="sm"
                    variant={active ? "secondary" : "default"}
                    onClick={() => setSelectedProjectId(project.id)}
                  >
                    {active ? "Currently active" : "Set as active job"}
                  </Button>
                  <Button size="sm" variant="outline" asChild>
                    <Link
                      to="/drawings"
                      onClick={() => setSelectedProjectId(project.id)}
                    >
                      Open register
                    </Link>
                  </Button>
                  <Button size="sm" variant="ghost" asChild>
                    <Link
                      to="/"
                      onClick={() => setSelectedProjectId(project.id)}
                    >
                      Command center
                    </Link>
                  </Button>
                </div>
              </article>
            );
          })}
        </div>
      </div>
    </AppShell>
  );
}

function Item({ label, value }: { label: string; value: string }) {
  return (
    <div>
      <dt className="text-[11px] uppercase tracking-wider text-[var(--color-subtle)]">
        {label}
      </dt>
      <dd className="text-[var(--color-fg)]">{value}</dd>
    </div>
  );
}

function Metric({
  label,
  value,
  tone = "default",
}: {
  label: string;
  value: string | number;
  tone?: "default" | "success" | "warn" | "danger";
}) {
  const color = {
    default: "text-[var(--color-fg)]",
    success: "text-[var(--color-success)]",
    warn: "text-[var(--color-warn)]",
    danger: "text-[var(--color-danger)]",
  }[tone];
  return (
    <div className="rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-bg-elevated)] px-3 py-2.5">
      <div className="text-[10px] uppercase tracking-wider text-[var(--color-subtle)]">
        {label}
      </div>
      <div className={`font-mono-num text-lg font-semibold ${color}`}>{value}</div>
    </div>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { toast } from "sonner";
import { AppShell } from "@/components/layout/app-shell";
import { RfiPriorityBadge, RfiStatusBadge } from "@/components/status-badges";
import { Button } from "@/components/ui/button";
import { Select } from "@/components/ui/select";
import {
  DISCIPLINE_LABELS,
  RFI_STATUS_LABELS,
  type RfiStatus,
} from "@/lib/types";
import { useAppStore, useSelectedProject } from "@/lib/store";
import { cn, daysUntil, formatDate } from "@/lib/utils";

export const Route = createFileRoute("/rfis")({
  component: RfisPage,
});

function RfisPage() {
  const project = useSelectedProject();
  const rfis = useAppStore((s) => s.rfis);
  const drawings = useAppStore((s) => s.drawings);
  const updateRfiStatus = useAppStore((s) => s.updateRfiStatus);
  const [statusFilter, setStatusFilter] = useState<RfiStatus | "all">("all");
  const [expanded, setExpanded] = useState<string | null>(null);

  const rows = useMemo(() => {
    return rfis
      .filter((r) => r.projectId === project?.id)
      .filter((r) => statusFilter === "all" || r.status === statusFilter)
      .sort((a, b) => {
        if (a.status === "open" && b.status !== "open") return -1;
        if (b.status === "open" && a.status !== "open") return 1;
        const order = { critical: 0, high: 1, normal: 2, low: 3 };
        return order[a.priority] - order[b.priority];
      });
  }, [rfis, project?.id, statusFilter]);

  return (
    <AppShell
      title="RFI Log"
      subtitle={
        project
          ? `${project.jobNumber} · questions holding detailing, fab, or erection`
          : undefined
      }
    >
      <div className="space-y-4">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <p className="max-w-2xl text-sm text-[var(--color-muted)]">
            RFIs are linked to drawings and piece marks so the shop and field know
            exactly which sheets are blocked — critical for connection holds and
            sequence releases.
          </p>
          <Select
            value={statusFilter}
            onChange={(e) => setStatusFilter(e.target.value as RfiStatus | "all")}
            className="w-40"
          >
            <option value="all">All statuses</option>
            {(Object.keys(RFI_STATUS_LABELS) as RfiStatus[]).map((s) => (
              <option key={s} value={s}>
                {RFI_STATUS_LABELS[s]}
              </option>
            ))}
          </Select>
        </div>

        <div className="space-y-3">
          {rows.length === 0 && (
            <div className="panel px-6 py-12 text-center text-sm text-[var(--color-muted)]">
              No RFIs for this filter.
            </div>
          )}
          {rows.map((rfi) => {
            const linked = drawings.filter((d) => rfi.drawingIds.includes(d.id));
            const due = daysUntil(rfi.dueDate);
            const isOpen = expanded === rfi.id;
            const overdue = rfi.status === "open" && due != null && due < 0;

            return (
              <article
                key={rfi.id}
                className={cn(
                  "panel overflow-hidden",
                  overdue && "border-[var(--color-danger)]/40",
                )}
              >
                <button
                  type="button"
                  className="flex w-full flex-col gap-2 px-5 py-4 text-left sm:flex-row sm:items-start sm:justify-between"
                  onClick={() => setExpanded(isOpen ? null : rfi.id)}
                >
                  <div className="min-w-0">
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-mono-num text-base font-semibold">
                        {rfi.number}
                      </span>
                      <RfiStatusBadge status={rfi.status} />
                      <RfiPriorityBadge priority={rfi.priority} />
                      <span className="text-[11px] uppercase tracking-wide text-[var(--color-subtle)]">
                        {DISCIPLINE_LABELS[rfi.discipline]}
                      </span>
                    </div>
                    <h2 className="mt-1 font-medium">{rfi.subject}</h2>
                    <div className="mt-1 text-xs text-[var(--color-muted)]">
                      Raised {formatDate(rfi.raisedDate)} by {rfi.raisedBy}
                      {rfi.dueDate && (
                        <>
                          {" "}
                          · Due{" "}
                          <span
                            className={cn(
                              "font-mono-num",
                              overdue
                                ? "text-[var(--color-danger)]"
                                : "text-[var(--color-fg)]",
                            )}
                          >
                            {formatDate(rfi.dueDate)}
                            {overdue && " (overdue)"}
                          </span>
                        </>
                      )}
                    </div>
                  </div>
                  <div className="flex flex-wrap gap-1.5 sm:justify-end">
                    {linked.map((d) => (
                      <span
                        key={d.id}
                        className="rounded-[var(--radius-sm)] border border-[var(--color-border)] px-2 py-0.5 font-mono-num text-[11px]"
                      >
                        {d.number}
                      </span>
                    ))}
                  </div>
                </button>

                {isOpen && (
                  <div className="space-y-4 border-t border-[var(--color-border)] px-5 py-4">
                    <div>
                      <div className="text-[11px] font-medium uppercase tracking-wider text-[var(--color-subtle)]">
                        Question
                      </div>
                      <p className="mt-1 text-sm leading-relaxed text-[var(--color-fg)]">
                        {rfi.question}
                      </p>
                    </div>
                    {rfi.answer && (
                      <div className="rounded-[var(--radius-lg)] border border-[var(--color-success)]/25 bg-[var(--color-success-bg)] px-4 py-3">
                        <div className="text-[11px] font-medium uppercase tracking-wider text-[var(--color-success)]">
                          Answer
                          {rfi.answeredDate
                            ? ` · ${formatDate(rfi.answeredDate)}`
                            : ""}
                        </div>
                        <p className="mt-1 text-sm leading-relaxed">{rfi.answer}</p>
                      </div>
                    )}
                    <div>
                      <div className="text-[11px] font-medium uppercase tracking-wider text-[var(--color-subtle)]">
                        Affected drawings
                      </div>
                      <div className="mt-2 flex flex-wrap gap-2">
                        {linked.map((d) => (
                          <Link
                            key={d.id}
                            to="/drawings/$drawingId"
                            params={{ drawingId: d.id }}
                            className="rounded-[var(--radius-md)] border border-[var(--color-border)] bg-[var(--color-bg-elevated)] px-3 py-2 text-xs hover:border-[var(--color-border-strong)]"
                          >
                            <span className="font-mono-num font-medium">{d.number}</span>
                            <span className="mt-0.5 block max-w-[180px] truncate text-[var(--color-muted)]">
                              {d.title}
                            </span>
                          </Link>
                        ))}
                      </div>
                    </div>
                    {rfi.status === "open" && (
                      <div className="flex flex-wrap gap-2">
                        <Button
                          size="sm"
                          onClick={() => {
                            updateRfiStatus(
                              rfi.id,
                              "answered",
                              rfi.answer ??
                                "Answer recorded — update detailing and release holds as required.",
                            );
                            toast.success(`${rfi.number} marked answered`);
                          }}
                        >
                          Mark answered
                        </Button>
                        <Button
                          size="sm"
                          variant="secondary"
                          onClick={() => {
                            updateRfiStatus(rfi.id, "closed");
                            toast.success(`${rfi.number} closed`);
                          }}
                        >
                          Close RFI
                        </Button>
                      </div>
                    )}
                    {rfi.status === "answered" && (
                      <Button
                        size="sm"
                        variant="secondary"
                        onClick={() => {
                          updateRfiStatus(rfi.id, "closed");
                          toast.success(`${rfi.number} closed`);
                        }}
                      >
                        Close RFI
                      </Button>
                    )}
                  </div>
                )}
              </article>
            );
          })}
        </div>
      </div>
    </AppShell>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { useMemo } from "react";
import { AppShell } from "@/components/layout/app-shell";
import { DrawingStatusBadge, SequenceStatusBadge } from "@/components/status-badges";
import { useAppStore, useSelectedProject } from "@/lib/store";
import { formatDate, formatTons } from "@/lib/utils";

export const Route = createFileRoute("/sequences")({
  component: SequencesPage,
});

function SequencesPage() {
  const project = useSelectedProject();
  const sequences = useAppStore((s) => s.sequences);
  const drawings = useAppStore((s) => s.drawings);

  const rows = useMemo(() => {
    return sequences
      .filter((s) => s.projectId === project?.id)
      .sort((a, b) => a.number - b.number)
      .map((seq) => {
        const seqDwgs = drawings
          .filter((d) => d.sequenceId === seq.id)
          .sort((a, b) => a.number.localeCompare(b.number));
        const ready = seqDwgs.filter((d) =>
          ["issued_for_fab", "issued_for_erection", "approved", "aan"].includes(
            d.status,
          ),
        ).length;
        const holds = seqDwgs.filter((d) => d.status === "on_hold").length;
        return { seq, seqDwgs, ready, holds };
      });
  }, [sequences, drawings, project?.id]);

  return (
    <AppShell
      title="Erection Sequences"
      subtitle={
        project
          ? `${project.jobNumber} · release order for detailing, fab, and field`
          : undefined
      }
    >
      <div className="space-y-4">
        <p className="max-w-3xl text-sm text-[var(--color-muted)]">
          Sequences mirror how steel actually leaves the shop and goes up in the air —
          not arbitrary work packages. Each sequence groups shop drawings, erection
          plans, and connection details that must clear together before the crane day.
        </p>

        {rows.length === 0 && (
          <div className="panel px-6 py-12 text-center text-sm text-[var(--color-muted)]">
            No sequences defined for this job.
          </div>
        )}

        {rows.map(({ seq, seqDwgs, ready, holds }) => (
          <article key={seq.id} className="panel overflow-hidden">
            <div className="flex flex-col gap-3 border-b border-[var(--color-border)] bg-[var(--color-bg-elevated)] px-5 py-4 sm:flex-row sm:items-start sm:justify-between">
              <div>
                <div className="flex flex-wrap items-center gap-2">
                  <h2 className="text-lg font-semibold tracking-tight">{seq.name}</h2>
                  <SequenceStatusBadge status={seq.status} />
                </div>
                <div className="mt-1 flex flex-wrap gap-x-4 gap-y-1 text-xs text-[var(--color-muted)]">
                  <span>Area: {seq.area}</span>
                  <span>Grids: {seq.grids}</span>
                  <span className="font-mono-num">{formatTons(seq.tonnage)}</span>
                </div>
                <div className="mt-1 text-xs text-[var(--color-subtle)]">
                  Planned {formatDate(seq.plannedStart)} → {formatDate(seq.plannedEnd)}
                </div>
              </div>
              <div className="rounded-[var(--radius-lg)] border border-[var(--color-border)] bg-[var(--color-surface)] px-4 py-3 text-sm">
                <div className="text-[11px] uppercase tracking-wider text-[var(--color-subtle)]">
                  Sheets ready
                </div>
                <div className="font-mono-num text-xl font-semibold">
                  {ready}
                  <span className="text-sm font-normal text-[var(--color-muted)]">
                    /{seqDwgs.length}
                  </span>
                </div>
                {holds > 0 && (
                  <div className="mt-1 text-xs text-[var(--color-warn)]">
                    {holds} sheet{holds === 1 ? "" : "s"} on hold
                  </div>
                )}
              </div>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full min-w-[560px] text-left text-sm">
                <thead>
                  <tr className="border-b border-[var(--color-border)] text-[11px] uppercase tracking-wider text-[var(--color-subtle)]">
                    <th className="px-5 py-2.5 font-medium">Dwg</th>
                    <th className="px-4 py-2.5 font-medium">Title</th>
                    <th className="px-4 py-2.5 font-medium">Rev</th>
                    <th className="px-4 py-2.5 font-medium">Status</th>
                    <th className="px-4 py-2.5 font-medium">Pieces</th>
                  </tr>
                </thead>
                <tbody>
                  {seqDwgs.length === 0 && (
                    <tr>
                      <td
                        colSpan={5}
                        className="px-5 py-6 text-[var(--color-muted)]"
                      >
                        No drawings assigned to this sequence yet.
                      </td>
                    </tr>
                  )}
                  {seqDwgs.map((d) => (
                    <tr
                      key={d.id}
                      className="border-b border-[var(--color-border)]/60 hover:bg-[var(--color-surface-2)]/40"
                    >
                      <td className="px-5 py-2.5">
                        <Link
                          to="/drawings/$drawingId"
                          params={{ drawingId: d.id }}
                          className="font-mono-num font-medium hover:underline"
                        >
                          {d.number}
                        </Link>
                      </td>
                      <td className="max-w-[240px] truncate px-4 py-2.5 text-[var(--color-muted)]">
                        {d.title}
                      </td>
                      <td className="px-4 py-2.5 font-mono-num">{d.currentRev}</td>
                      <td className="px-4 py-2.5">
                        <DrawingStatusBadge status={d.status} />
                      </td>
                      <td className="px-4 py-2.5 font-mono-num text-xs text-[var(--color-muted)]">
                        {d.pieceMarks.slice(0, 4).join(", ") || "—"}
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </article>
        ))}
      </div>
    </AppShell>
  );
}

import { createFileRoute, Link } from "@tanstack/react-router";
import { useMemo, useState } from "react";
import { AppShell } from "@/components/layout/app-shell";
import { SubmittalStatusBadge } from "@/components/status-badges";
import { Select } from "@/components/ui/select";
import {
  SUBMITTAL_STATUS_LABELS,
  SUBMITTAL_TYPE_LABELS,
  type SubmittalStatus,
} from "@/lib/types";
import { useAppStore, useSelectedProject } from "@/lib/store";
import { formatDate } from "@/lib/utils";

export const Route = createFileRoute("/submittals")({
  component: SubmittalsPage,
});

function SubmittalsPage() {
  const project = useSelectedProject();
  const submittals = useAppStore((s) => s.submittals);
  const drawings = useAppStore((s) => s.drawings);
  const [statusFilter, setStatusFilter] = useState<SubmittalStatus | "all">("all");

  const rows = useMemo(() => {
    return submittals
      .filter((s) => s.projectId === project?.id)
      .filter((s) => statusFilter === "all" || s.status === statusFilter)
      .sort((a, b) => (b.submittedDate ?? "").localeCompare(a.submittedDate ?? ""));
  }, [submittals, project?.id, statusFilter]);

  const openCount = submittals.filter(
    (s) =>
      s.projectId === project?.id &&
      ["submitted", "under_review", "resubmit"].includes(s.status),
  ).length;

  return (
    <AppShell
      title="Submittal Log"
      subtitle={
        project
          ? `${project.jobNumber} · packages to ${project.engineer}`
          : undefined
      }
    >
      <div className="space-y-4">
        <div className="flex flex-col gap-3 sm:flex-row sm:items-end sm:justify-between">
          <p className="max-w-2xl text-sm text-[var(--color-muted)]">
            Track shop drawing packages, erection sets, and resubmittals the way the
            GC and EOR actually review them — not as a generic document list.
          </p>
          <div className="flex items-center gap-3">
            <div className="text-xs text-[var(--color-muted)]">
              <span className="font-mono-num text-[var(--color-warn)]">{openCount}</span>{" "}
              open packages
            </div>
            <Select
              value={statusFilter}
              onChange={(e) =>
                setStatusFilter(e.target.value as SubmittalStatus | "all")
              }
              className="w-44"
            >
              <option value="all">All statuses</option>
              {(Object.keys(SUBMITTAL_STATUS_LABELS) as SubmittalStatus[]).map(
                (s) => (
                  <option key={s} value={s}>
                    {SUBMITTAL_STATUS_LABELS[s]}
                  </option>
                ),
              )}
            </Select>
          </div>
        </div>

        <div className="space-y-3">
          {rows.length === 0 && (
            <div className="panel px-6 py-12 text-center text-sm text-[var(--color-muted)]">
              No submittals match this filter.
            </div>
          )}
          {rows.map((sub) => {
            const sheets = drawings.filter((d) => sub.drawingIds.includes(d.id));
            return (
              <article key={sub.id} className="panel p-5">
                <div className="flex flex-col gap-3 sm:flex-row sm:items-start sm:justify-between">
                  <div>
                    <div className="flex flex-wrap items-center gap-2">
                      <span className="font-mono-num text-lg font-semibold">
                        {sub.number}
                      </span>
                      <SubmittalStatusBadge status={sub.status} />
                      <span className="rounded-full border border-[var(--color-border)] px-2 py-0.5 text-[11px] uppercase tracking-wide text-[var(--color-muted)]">
                        {SUBMITTAL_TYPE_LABELS[sub.packageType]}
                      </span>
                    </div>
                    <h2 className="mt-1 font-medium">{sub.title}</h2>
                    <div className="mt-1 text-xs text-[var(--color-muted)]">
                      Reviewer: {sub.reviewer ?? "—"} · Submitted{" "}
                      {formatDate(sub.submittedDate)}
                      {sub.returnedDate
                        ? ` · Returned ${formatDate(sub.returnedDate)}`
                        : ""}
                    </div>
                  </div>
                  <div className="font-mono-num text-sm text-[var(--color-subtle)]">
                    {sheets.length} sheet{sheets.length === 1 ? "" : "s"}
                  </div>
                </div>

                {sub.notes && (
                  <p className="mt-3 rounded-[var(--radius-md)] border border-[var(--color-border)] bg-[var(--color-bg-elevated)] px-3 py-2 text-sm text-[var(--color-muted)]">
                    {sub.notes}
                  </p>
                )}

                <div className="mt-4 flex flex-wrap gap-2">
                  {sheets.map((d) => (
                    <Link
                      key={d.id}
                      to="/drawings/$drawingId"
                      params={{ drawingId: d.id }}
                      className="inline-flex items-center gap-1.5 rounded-[var(--radius-md)] border border-[var(--color-border)] bg-[var(--color-bg-elevated)] px-2.5 py-1.5 text-xs hover:border-[var(--color-border-strong)]"
                    >
                      <span className="font-mono-num font-medium">{d.number}</span>
                      <span className="text-[var(--color-subtle)]">
                        Rev {d.currentRev}
                      </span>
                    </Link>
                  ))}
                </div>
              </article>
            );
          })}
        </div>
      </div>
    </AppShell>
  );
}

@import "tailwindcss";
@import "tw-animate-css";

@theme {
  --font-sans: "IBM Plex Sans", "Segoe UI", system-ui, -apple-system, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, "SF Mono", Menlo, Consolas, monospace;

  --color-bg: #0c0d0f;
  --color-bg-elevated: #13151a;
  --color-surface: #181b21;
  --color-surface-2: #1e2229;
  --color-fg: #e8eaed;
  --color-muted: #9aa0a8;
  --color-subtle: #6b7280;
  --color-border: #2a2f38;
  --color-border-strong: #3a4150;
  --color-primary: #c5ccd6;
  --color-primary-fg: #0c0d0f;
  --color-accent: #7d93a8;
  --color-ring: #8b9aab;

  --color-success: #5f8f6e;
  --color-success-bg: #152018;
  --color-warn: #b8924a;
  --color-warn-bg: #221c10;
  --color-danger: #b86a62;
  --color-danger-bg: #221412;
  --color-info: #6a8fad;
  --color-info-bg: #121820;

  --radius-xs: 0.25rem;
  --radius-sm: 0.375rem;
  --radius-md: 0.5rem;
  --radius-lg: 0.75rem;
  --radius-xl: 1rem;

  --shadow-panel: 0 1px 0 rgba(255, 255, 255, 0.03) inset, 0 8px 24px rgba(0, 0, 0, 0.28);
}

@layer base {
  * {
    border-color: var(--color-border);
  }

  html {
    color-scheme: dark;
  }

  body {
    margin: 0;
    min-height: 100dvh;
    background: var(--color-bg);
    color: var(--color-fg);
    font-family: var(--font-sans);
    font-size: 0.9375rem;
    line-height: 1.5;
    -webkit-font-smoothing: antialiased;
  }

  button:not(:disabled),
  [role="button"]:not(:disabled) {
    cursor: pointer;
  }

  ::selection {
    background: color-mix(in oklab, var(--color-accent) 35%, transparent);
  }
}

@layer utilities {
  .font-mono-num {
    font-family: var(--font-mono);
    font-variant-numeric: tabular-nums;
  }

  .panel {
    background: var(--color-surface);
    border: 1px solid var(--color-border);
    border-radius: var(--radius-xl);
    box-shadow: var(--shadow-panel);
  }

  .steel-grid {
    background-image:
      linear-gradient(to right, color-mix(in oklab, var(--color-border) 55%, transparent) 1px, transparent 1px),
      linear-gradient(to bottom, color-mix(in oklab, var(--color-border) 55%, transparent) 1px, transparent 1px);
    background-size: 24px 24px;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

#!/usr/bin/env node
/**
 * Deploy-time database migrator (node-postgres, `pg`).
 *
 * Runs during `npm run build` — on every Vercel deploy — applying pending files
 * in ../migrations to DATABASE_URL. Each file is applied in one transaction and
 * recorded in a `_migrations` table, so it runs once and is safe to re-run.
 *
 * No DATABASE_URL (local / preview builds) -> skip; the PGLite fallback applies
 * the same files at startup instead (see src/lib/db.ts).
 */
import { readdir, readFile } from "node:fs/promises";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import pg from "pg";

const databaseUrl = process.env.DATABASE_URL;
if (!databaseUrl) {
  console.log(
    "[migrate] DATABASE_URL not set — skipping (the PGLite fallback migrates itself).",
  );
  process.exit(0);
}

const migrationsDir = join(dirname(fileURLToPath(import.meta.url)), "..", "migrations");

async function main() {
  const pool = new pg.Pool({ connectionString: databaseUrl, max: 1 });
  const client = await pool.connect();
  try {
    await client.query(
      "CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY, applied_at TIMESTAMPTZ NOT NULL DEFAULT now())",
    );
    const applied = new Set(
      (await client.query("SELECT name FROM _migrations")).rows.map((r) => r.name),
    );

    let files;
    try {
      files = (await readdir(migrationsDir)).filter((f) => f.endsWith(".sql")).sort();
    } catch {
      console.log("[migrate] no migrations/ directory — nothing to do.");
      return;
    }

    let count = 0;
    for (const name of files) {
      if (applied.has(name)) continue;
      const text = await readFile(join(migrationsDir, name), "utf8");
      try {
        await client.query("BEGIN");
        // pg's simple-query protocol runs a whole multi-statement file at once.
        await client.query(text);
        await client.query("INSERT INTO _migrations (name) VALUES ($1)", [name]);
        await client.query("COMMIT");
      } catch (err) {
        console.error(`[migrate] error applying ${name}`);
        try {
          await client.query("ROLLBACK");
        } catch {
          // ROLLBACK fails when the connection died — keep the original error.
        }
        throw err;
      }
      console.log(`[migrate] applied ${name}`);
      count += 1;
    }
    console.log(count ? `[migrate] done — ${count} migration(s) applied.` : "[migrate] up to date.");
  } finally {
    client.release();
    await pool.end();
  }
}

main().catch((err) => {
  console.error("[migrate] failed:", err?.message || err);
  // pg errors carry the context needed to debug a bad SQL file.
  for (const key of ["code", "detail", "hint", "position", "where"]) {
    if (err?.[key] != null) console.error(`[migrate]   ${key}: ${err[key]}`);
  }
  process.exit(1);
});

